## Source Files

### `src/capitalize.ts`
```typescript
/**
 * Capitalizes the first letter of a string and lowercases the rest.
 * Returns an empty string if the input is empty.
 */
export function capitalize(value: string): string {
  if (value.length === 0) return "";
  return value.charAt(0).toUpperCase() + value.slice(1).toLowerCase();
}
```

---

### `src/truncate.ts`
```typescript
/**
 * Truncates a string to a maximum length, appending a suffix if cut.
 * @param value   - The string to truncate.
 * @param maxLength - Maximum allowed length (including suffix).
 * @param suffix  - Appended when truncation occurs (default: "...").
 */
export function truncate(
  value: string,
  maxLength: number,
  suffix: string = "..."
): string {
  if (maxLength < 0) throw new RangeError("maxLength must be non-negative");
  if (value.length <= maxLength) return value;

  const trimLength = maxLength - suffix.length;
  if (trimLength <= 0) return suffix.slice(0, maxLength);

  return value.slice(0, trimLength) + suffix;
}
```

