## Test Files

### `tests/capitalize.test.ts`
```typescript
import { capitalize } from "../src";

describe("capitalize()", () => {
  it("capitalizes the first letter and lowercases the rest", () => {
    expect(capitalize("hello")).toBe("Hello");
    expect(capitalize("WORLD")).toBe("World");
    expect(capitalize("javaScript")).toBe("Javascript");
  });

  it("handles a single character", () => {
    expect(capitalize("a")).toBe("A");
    expect(capitalize("Z")).toBe("Z");
  });

  it("returns an empty string when given an empty string", () => {
    expect(capitalize("")).toBe("");
  });

  it("handles strings that start with a number or symbol", () => {
    expect(capitalize("123abc")).toBe("123abc");
    expect(capitalize("!hello")).toBe("!hello");
  });
});
```

---

### `tests/truncate.test.ts`
```typescript
import { truncate } from "../src";

describe("truncate()", () => {
  it("returns the original string when within maxLength", () => {
    expect(truncate("hello", 10)).toBe("hello");
    expect(truncate("hello", 5)).toBe("hello");  // exact length — no truncation
  });

  it("truncates and appends the default suffix '...'", () => {
    expect(truncate("Hello, World!", 8)).toBe("Hello...");
  });

  it("truncates and appends a custom suffix", () => {
    expect(truncate("Hello, World!", 7, "…")).toBe("Hello, …");
  });

  it("returns only the suffix when trimLength is zero or less", () => {
    expect(truncate("Hello", 3)).toBe("...");   // suffix fills entire budget
    expect(truncate("Hello", 2)).toBe("..");    // suffix itself is clipped
  });

  it("handles an empty string", () => {
    expect(truncate("", 5)).toBe("");
  });

  it("throws RangeError for a negative maxLength", () => {
    expect(() => truncate("hello", -1)).toThrow(RangeError);
    expect(() => truncate("hello", -1)).toThrow("maxLength must be non-negative");
  });
});
```

