/**
 * Truncates a string to a maximum length, appending a suffix if cut.
 * @param value   - The string to truncate.
 * @param maxLen  - Maximum allowed length (including suffix).
 * @param suffix  - Appended when truncation occurs (default: "...").
 */
export function truncate(
  value: string,
  maxLen: number,
  suffix: string = "..."
): string {
  if (maxLen < 0) throw new RangeError("maxLen must be >= 0");
  if (value.length <= maxLen) return value;

  const trimLen = maxLen - suffix.length;
  if (trimLen <= 0) return suffix.slice(0, maxLen);

  return value.slice(0, trimLen) + suffix;
}
