'use strict';

const storage = require('../lib/storage');
const { success, error } = require('../lib/formatter');

/**
 * Registers the `add` command on the given Commander program.
 * Usage: tally add <item> [--count <n>]
 *
 * @param {import('commander').Command} program
 */
function add(program) {
  program
    .command('add <item>')
    .description('Add or increment a tally item')
    .option('-c, --count <n>', 'Amount to add', '1')
    .action((item, options) => {
      const count = parseInt(options.count, 10);

      if (isNaN(count) || count < 1) {
        console.error(error(`--count must be a positive integer`));
        process.exit(1);
      }

      const store = storage.load();
      store[item] = (store[item] ?? 0) + count;
      storage.save(store);

      console.log(success(`Added ${count} to "${item}" → total: ${store[item]}`));
    });
}

module.exports = add;
```

