'use strict';

const storage = require('../lib/storage');
const { formatTable } = require('../lib/formatter');

/**
 * Registers the `list` command.
 * Usage: tally list [--sort]
 *
 * @param {import('commander').Command} program
 */
function list(program) {
  program
    .command('list')
    .description('List all tally items')
    .option('-s, --sort', 'Sort by count descending')
    .action((options) => {
      const store = storage.load();
      const entries = Object.entries(store);

      if (entries.length === 0) {
        console.log('No items tallied yet.');
        return;
      }

      const sorted = options.sort
        ? entries.sort(([, a], [, b]) => b - a)
        : entries;

      console.log(formatTable(sorted));
    });
}

module.exports = list;
