### `src/lib/storage.js`
```js
'use strict';

const fs   = require('fs');
const path = require('path');
const { StorageError } = require('./errors');

// Store data in the user's home directory
const STORE_PATH = path.join(
  process.env.HOME || process.env.USERPROFILE || '.',
  '.tally-store.json'
);

/**
 * Load the tally store from disk.
 * Returns an empty object if the file doesn't exist yet.
 *
 * @returns {Record<string, number>}
 */
function load() {
  try {
    if (!fs.existsSync(STORE_PATH)) return {};
    const raw = fs.readFileSync(STORE_PATH, 'utf8');
    return JSON.parse(raw);
  } catch (err) {
    throw new StorageError(`Failed to load store: ${err.message}`);
  }
}

/**
 * Persist the tally store to disk.
 *
 * @param {Record<string, number>} store
 */
function save(store) {
  try {
    fs.writeFileSync(STORE_PATH, JSON.stringify(store, null, 2), 'utf8');
  } catch (err) {
    throw new StorageError(`Failed to save store: ${err.message}`);
  }
}

module.exports = { load, save, STORE_PATH };
```

