'use strict';

// Mock storage so tests never touch the real filesystem
jest.mock('../../src/lib/storage');

const storage   = require('../../src/lib/storage');
const { Command } = require('commander');
const addCommand  = require('../../src/commands/add');

// ─── Helpers ────────────────────────────────────────────────────────────────

/** Build a fresh Commander instance with only the `add` command registered. */
function buildProgram() {
  const program = new Command();
  program.exitOverride();          // throw instead of process.exit
  addCommand(program);
  return program;
}

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('tally add', () => {
  let consoleSpy;

  beforeEach(() => {
    jest.clearAllMocks();
    consoleSpy = jest.spyOn(console, 'log').mockImplementation(() => {});
    storage.load.mockReturnValue({});   // start with empty store each time
    storage.save.mockImplementation(() => {});
  });

  afterEach(() => {
    consoleSpy.mockRestore();
  });

  test('adds a new item with default count of 1', () => {
    buildProgram().parse(['add', 'apples'], { from: 'user' });

    expect(storage.save).toHaveBeenCalledWith({ apples: 1 });
    expect(consoleSpy).toHaveBeenCalledWith(
      expect.stringContaining('total: 1')
    );
  });

  test('increments an existing item', () => {
    storage.load.mockReturnValue({ apples: 3 });

    buildProgram().parse(['add', 'apples'], { from: 'user' });

    expect(storage.save).toHaveBeenCalledWith({ apples: 4 });
  });

  test('respects --count flag', () => {
    buildProgram().parse(['add', 'apples', '--count', '5'], { from: 'user' });

    expect(storage.save).toHaveBeenCalledWith({ apples: 5 });
    expect(consoleSpy).toHaveBeenCalledWith(
      expect.stringContaining('total: 5')
    );
  });

  test('exits with error for non-numeric --count', () => {
    const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
    const exitSpy  = jest.spyOn(process, 'exit').mockImplementation(() => {});

    buildProgram().parse(['add', 'apples', '--count', 'abc'], { from: 'user' });

    expect(exitSpy).toHaveBeenCalledWith(1);
    expect(storage.save).not.toHaveBeenCalled();

    errorSpy.mockRestore();
    exitSpy.mockRestore();
  });
});
