const storage = require("../lib/storage");

/**
 * Registers the `add` command.
 * Usage: tally add <item> [count]
 *
 * @param {import("commander").Command} program
 */
function addCommand(program) {
  program
    .command("add <item> [count]")
    .description("Add an item to the tally")
    .action((item, count = "1") => {
      const amount = parseInt(count, 10);

      if (isNaN(amount) || amount < 1) {
        console.error("Error: count must be a positive integer.");
        process.exit(1);
      }

      const data = storage.load();

      // Increment existing or initialise at zero
      data[item] = (data[item] ?? 0) + amount;

      storage.save(data);
      console.log(`Added ${amount} to "${item}". New total: ${data[item]}`);
    });
}

module.exports = addCommand;
