'use strict';

const storage = require('../lib/storage');
const { TallyError } = require('../lib/errors');

/**
 * Register the `add` command.
 * @param {import('commander').Command} program
 */
function register(program) {
  program
    .command('add <item>')
    .description('Increment the tally for an item')
    .option('-n, --amount <number>', 'Amount to add', '1')
    .action((item, options) => {
      execute(item, options).catch((err) => {
        console.error(err.message);
        process.exit(1);
      });
    });
}

/**
 * Core logic — separated from Commander so it is unit-testable.
 * @param {string} item
 * @param {{ amount: string }} options
 * @returns {Promise<{ item: string, count: number }>}
 */
async function execute(item, options = { amount: '1' }) {
  const amount = parseInt(options.amount, 10);

  if (isNaN(amount) || amount <= 0) {
    throw new TallyError(`--amount must be a positive integer, got "${options.amount}"`);
  }

  const data  = await storage.load();
  const prev  = data[item] ?? 0;
  data[item]  = prev + amount;

  await storage.save(data);

  console.log(`✔  ${item}: ${prev} → ${data[item]}`);
  return { item, count: data[item] };
}

module.exports = { register, execute };
```

