'use strict';

const fs   = require('fs');
const path = require('path');

const STORE_PATH = path.join(
  process.env.TALLY_STORE_DIR ?? process.env.HOME ?? '.',
  '.tally-store.json'
);

/**
 * Load the store from disk. Returns an empty object if the file
 * does not exist yet.
 * @returns {Record<string, number>}
 */
function load() {
  if (!fs.existsSync(STORE_PATH)) return {};

  try {
    const raw = fs.readFileSync(STORE_PATH, 'utf8');
    return JSON.parse(raw);
  } catch {
    throw new Error(`Failed to parse store at ${STORE_PATH}`);
  }
}

/**
 * Persist the store to disk.
 * @param {Record<string, number>} store
 */
function save(store) {
  fs.writeFileSync(STORE_PATH, JSON.stringify(store, null, 2), 'utf8');
}

module.exports = { load, save, STORE_PATH };
