### `src/lib/formatter.js`
```js
'use strict';

const chalk = require('chalk');

const COL_WIDTH = 20;

module.exports = {
  /**
   * Format a success message in green.
   * @param {string} msg
   */
  success: (msg) => chalk.green(`✔  ${msg}`),

  /**
   * Format an error message in red.
   * @param {string} msg
   */
  error: (msg) => chalk.red(`✖  ${msg}`),

  /**
   * Render a store object as a simple aligned table.
   * @param {Record<string, number>} store
   */
  table(store) {
    const header = chalk.bold(
      'ITEM'.padEnd(COL_WIDTH) + 'COUNT'
    );
    const divider = '─'.repeat(COL_WIDTH + 10);

    const rows = Object.entries(store)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([item, count]) =>
        item.padEnd(COL_WIDTH) + chalk.cyan(count)
      );

    return [header, divider, ...rows].join('\n');
  },
};
