const storage = require('../lib/storage');
const logger  = require('../utils/logger');

/**
 * Registers the `add` command.
 * Usage: tally add <item> [--count <n>]
 * @param {import('commander').Command} program
 */
function register(program) {
  program
    .command('add <item>')
    .description('Add or increment a tally item')
    .option('-c, --count <number>', 'Amount to add', '1')
    .action((item, options) => {
      const amount = parseInt(options.count, 10);

      if (isNaN(amount) || amount < 1) {
        logger.error('--count must be a positive integer');
        process.exit(1);
      }

      const data        = storage.load();
      data[item]        = (data[item] ?? 0) + amount;
      storage.save(data);

      logger.success(`Added ${amount} to "${item}" → total: ${data[item]}`);
    });
}

/**
 * Pure logic — separated so unit tests don't need Commander.
 * @param {Record<string, number>} data
 * @param {string} item
 * @param {number} amount
 * @returns {Record<string, number>} updated data
 */
function execute(data, item, amount = 1) {
  if (!item || typeof item !== 'string') throw new Error('Item must be a non-empty string');
  if (!Number.isInteger(amount) || amount < 1) throw new Error('Amount must be a positive integer');

  return { ...data, [item]: (data[item] ?? 0) + amount };
}

module.exports = { register, execute };
