import { Command } from 'commander';
import { addCommand }    from './commands/add.js';
import { removeCommand } from './commands/remove.js';
import { listCommand }   from './commands/list.js';
import { resetCommand }  from './commands/reset.js';

/**
 * Build and return the root Commander program.
 * Exported separately so tests can call it without side effects.
 */
export function buildProgram() {
  const program = new Command();

  program
    .name('tally')
    .description('Track and count items from the command line')
    .version('1.0.0');

  program.addCommand(addCommand());
  program.addCommand(removeCommand());
  program.addCommand(listCommand());
  program.addCommand(resetCommand());

  return program;
}

/** Parse argv and execute — called only from bin/tally.js */
export function run(argv = process.argv) {
  buildProgram().parse(argv);
}
