```js
import { Command } from 'commander';
import { readData, writeData } from '../lib/storage.js';
import { NotFoundError } from '../lib/errors.js';

/**
 * tally add <item> [amount]
 * Increments the count for <item> by [amount] (default: 1).
 */
export function addCommand() {
  return new Command('add')
    .description('Increment the count for an item')
    .argument('<item>', 'Item name to tally')
    .argument('[amount]', 'Amount to add', '1')
    .action(async (item, amount) => {
      const delta = parseInt(amount, 10);

      if (isNaN(delta) || delta <= 0) {
        console.error('Amount must be a positive integer.');
        process.exit(1);
      }

      const data = await readData();
      data[item] = (data[item] ?? 0) + delta;
      await writeData(data);

      console.log(`✔  ${item}: ${data[item]}`);
    });
}
