import { Command } from 'commander';
import { readData } from '../lib/storage.js';
import { formatTable } from '../lib/formatter.js';

/**
 * tally list [--sort]
 * Prints all tracked items and their counts.
 */
export function listCommand() {
  return new Command('list')
    .description('List all tracked items and their counts')
    .option('-s, --sort', 'Sort items by count (descending)')
    .action(async (options) => {
      const data = await readData();
      const entries = Object.entries(data);

      if (entries.length === 0) {
        console.log('No items tracked yet. Use `tally add <item>` to start.');
        return;
      }

      const sorted = options.sort
        ? entries.sort(([, a], [, b]) => b - a)
        : entries;

      console.log(formatTable(sorted));
    });
}
