### `src/lib/formatter.js`
```js
/**
 * Render an array of [name, count] pairs as a padded table string.
 * @param {[string, number][]} entries
 * @returns {string}
 */
export function formatTable(entries) {
  const maxLen = Math.max(...entries.map(([name]) => name.length));

  const rows = entries.map(([name, count]) => {
    const padded = name.padEnd(maxLen, ' ');
    return `  ${padded}  ${count}`;
  });

  const divider = '─'.repeat(maxLen + 6);
  return [divider, ...rows, divider].join('\n');
}
```

