import { readData, writeData } from '../lib/storage.js';
import { validateItemName }    from '../utils/validate.js';
import { formatSuccess }       from '../lib/formatter.js';

/**
 * Registers the `add` command on the given Commander program.
 *
 * Usage: tally add <item> [--count <n>]
 *
 * @param {import('commander').Command} program
 */
export function addCommand(program) {
  program
    .command('add <item>')
    .description('Add an item or increment its count')
    .option('-c, --count <number>', 'Number to add', '1')
    .action((item, options) => {
      validateItemName(item);                    // throws on invalid input

      const count = parseInt(options.count, 10);
      const data  = readData();

      data[item] = (data[item] ?? 0) + count;   // create or increment
      writeData(data);

      console.log(formatSuccess(`Added ${count} to "${item}". New total: ${data[item]}`));
    });
}
