import fs   from 'fs';
import path from 'path';

// Store data in the user's home directory so it persists across sessions
const DATA_PATH = path.join(process.env.HOME || process.cwd(), '.tally-data.json');

/**
 * Reads the tally data file.
 * Returns an empty object if the file does not yet exist.
 *
 * @returns {Record<string, number>}
 */
export function readData() {
  if (!fs.existsSync(DATA_PATH)) return {};

  const raw = fs.readFileSync(DATA_PATH, 'utf-8');
  return JSON.parse(raw);
}

/**
 * Writes the tally data object back to disk.
 *
 * @param {Record<string, number>} data
 */
export function writeData(data) {
  fs.writeFileSync(DATA_PATH, JSON.stringify(data, null, 2), 'utf-8');
}

// Export path so tests can override it via jest.mock or dependency injection
export { DATA_PATH };
