import { TallyValidationError } from './errors.js';

/**
 * Ensures an item name is a non-empty string with no special characters.
 *
 * @param {string} name
 * @throws {TallyValidationError}
 */
export function validateItemName(name) {
  if (!name || typeof name !== 'string') {
    throw new TallyValidationError('Item name must be a non-empty string.');
  }
  if (!/^[\w\s-]+$/.test(name)) {
    throw new TallyValidationError(
      `Invalid item name "${name}". Only letters, numbers, spaces, and hyphens are allowed.`
    );
  }
}
