import { Command } from 'commander';
import { readData, writeData } from '../lib/storage.js';
import { validateItem }        from '../utils/validateInput.js';
import { logger }              from '../utils/logger.js';

export const addCommand = new Command('add')
  .description('Add or increment an item in the tally')
  .argument('<item>', 'Item name to tally')
  .option('-n, --count <number>', 'Amount to add', '1')
  .action((item, options) => {
    validateItem(item);                          // throws on bad input

    const count = parseInt(options.count, 10);
    if (isNaN(count) || count < 1) {
      logger.error('--count must be a positive integer');
      process.exit(1);
    }

    const data = readData();
    data[item] = (data[item] ?? 0) + count;
    writeData(data);

    logger.success(`Added ${count} to "${item}" → total: ${data[item]}`);
  });
```

