'use strict';

const storage   = require('../lib/storage');
const formatter = require('../lib/formatter');

/**
 * Register the `add` command.
 * @param {import('commander').Command} program
 */
function register(program) {
  program
    .command('add <item>')
    .description('Increment the tally for an item')
    .option('-n, --amount <number>', 'Amount to add', '1')
    .action((item, options) => {
      const amount = parseInt(options.amount, 10);

      if (isNaN(amount) || amount < 1) {
        console.error(formatter.error('Amount must be a positive integer.'));
        process.exit(1);
      }

      const data        = storage.load();
      data[item]        = (data[item] ?? 0) + amount;
      storage.save(data);

      console.log(formatter.success(`Added ${amount} to "${item}". New total: ${data[item]}`));
    });
}

module.exports = { register };
