```js
const storage   = require("../lib/storage");
const formatter = require("../lib/formatter");

/**
 * Registers the `add` command.
 * Usage: tally add <item> [--count <n>]
 */
module.exports = function addCommand(program) {
  program
    .command("add <item>")
    .description("Add or increment an item in the tally")
    .option("-c, --count <number>", "Amount to add", "1")
    .action((item, options) => {
      const count = parseInt(options.count, 10);

      if (isNaN(count) || count < 1) {
        console.error(formatter.error("Count must be a positive integer."));
        process.exit(1);
      }

      const data = storage.load();
      data[item] = (data[item] ?? 0) + count;
      storage.save(data);

      console.log(formatter.success(`Added ${count} to "${item}". New total: ${data[item]}`));
    });
};
```

