### `src/lib/storage.js`
```js
const fs   = require("fs");
const path = require("path");

const DATA_FILE = path.join(
  process.env.TALLY_DATA_DIR ?? process.env.HOME ?? ".",
  ".tally-data.json"
);

/**
 * Loads tally data from disk.
 * @returns {Record<string, number>}
 */
function load() {
  if (!fs.existsSync(DATA_FILE)) return {};

  try {
    const raw = fs.readFileSync(DATA_FILE, "utf-8");
    return JSON.parse(raw);
  } catch {
    return {};
  }
}

/**
 * Saves tally data to disk.
 * @param {Record<string, number>} data
 */
function save(data) {
  fs.writeFileSync(DATA_FILE, JSON.stringify(data, null, 2), "utf-8");
}

/**
 * Returns the resolved path to the data file (useful for tests).
 */
function getDataFilePath() {
  return DATA_FILE;
}

module.exports = { load, save, getDataFilePath };
