### `src/lib/formatter.js`
```js
const chalk = require("chalk");

module.exports = {
  success: (msg) => chalk.green(`✔  ${msg}`),
  error:   (msg) => chalk.red(`✖  ${msg}`),
  info:    (msg) => chalk.cyan(`ℹ  ${msg}`),

  /**
   * Formats the full tally list for display.
   * @param {Record<string, number>} data
   * @returns {string}
   */
  formatList(data) {
    const entries = Object.entries(data);

    if (entries.length === 0) {
      return chalk.yellow("No items in tally yet.");
    }

    const rows = entries
      .sort(([, a], [, b]) => b - a)           // sort by count descending
      .map(([item, count]) =>
        `  ${chalk.bold(item.padEnd(20))} ${chalk.cyan(count)}`
      );

    return ["", chalk.underline("Current Tally:"), ...rows, ""].join("\n");
  },
};
```

