'use strict';

const store    = require('../lib/store');
const logger   = require('../utils/logger');
const validate = require('../utils/validate');

/**
 * Registers the `add` command.
 * Usage: tally add <item> [count]
 * @param {import('commander').Command} program
 */
function addCommand(program) {
  program
    .command('add <item> [count]')
    .description('Add or increment an item in the tally')
    .option('-s, --silent', 'Suppress output')
    .action((item, count = '1', options) => {
      validate.itemName(item);         // throws on invalid input

      const amount  = validate.count(count);
      const tallies = store.read();

      tallies[item] = (tallies[item] ?? 0) + amount;
      store.write(tallies);

      if (!options.silent) {
        logger.success(`Added ${amount} to "${item}". New total: ${tallies[item]}`);
      }
    });
}

module.exports = addCommand;
