'use strict';

/**
 * Validates that an item name is a non-empty string.
 * @param {string} name
 */
function itemName(name) {
  if (!name || typeof name !== 'string' || name.trim() === '') {
    throw new Error('Item name must be a non-empty string.');
  }
}

/**
 * Validates and parses a count argument.
 * @param   {string} value
 * @returns {number}
 */
function count(value) {
  const parsed = parseInt(value, 10);
  if (isNaN(parsed) || parsed < 1) {
    throw new Error(`Count must be a positive integer. Received: "${value}"`);
  }
  return parsed;
}

module.exports = { itemName, count };
