const { Command } = require('commander');
const { readStore, writeStore } = require('../lib/storage');
const { formatCount } = require('../lib/formatter');
const { NotFoundError } = require('../lib/errors');

const addCommand = new Command('add')
  .description('Increment the count for an item')
  .argument('<item>', 'Name of the item to tally')
  .option('-n, --amount <number>', 'Amount to add', '1')
  .action((item, options) => {
    const amount = parseInt(options.amount, 10);

    if (isNaN(amount) || amount < 1) {
      console.error('--amount must be a positive integer');
      process.exit(1);
    }

    const store = readStore();
    store[item] = (store[item] ?? 0) + amount;
    writeStore(store);

    console.log(formatCount(item, store[item]));
  });

module.exports = { addCommand };
