### `src/lib/storage.js`
```js
const fs   = require('fs');
const path = require('path');

// Store data in the user's home directory
const STORE_PATH = path.join(
  process.env.HOME || process.env.USERPROFILE,
  '.tally-store.json'
);

/**
 * Read the JSON data store from disk.
 * Returns an empty object if the file does not exist.
 * @returns {Record<string, number>}
 */
function readStore(filePath = STORE_PATH) {
  try {
    const raw = fs.readFileSync(filePath, 'utf-8');
    return JSON.parse(raw);
  } catch (err) {
    if (err.code === 'ENOENT') return {};   // File not found → fresh store
    throw err;                              // Re-throw unexpected errors
  }
}

/**
 * Write the data store object to disk as JSON.
 * @param {Record<string, number>} store
 * @param {string} filePath
 */
function writeStore(store, filePath = STORE_PATH) {
  fs.writeFileSync(filePath, JSON.stringify(store, null, 2), 'utf-8');
}

module.exports = { readStore, writeStore, STORE_PATH };
```

