### `src/lib/formatter.js`
```js
/**
 * Format tally data as an aligned table string.
 * @param {Record<string, number>} data
 * @returns {string}
 */
function formatTable(data) {
  const entries = Object.entries(data);

  if (entries.length === 0) {
    return '(no items tallied yet)';
  }

  const maxLen = Math.max(...entries.map(([key]) => key.length));

  return entries
    .sort(([, a], [, b]) => b - a)               // sort descending by count
    .map(([key, val]) => `${key.padEnd(maxLen)}  ${val}`)
    .join('\n');
}

module.exports = { formatTable };
```

