'use strict';

const { Command } = require('commander');
const store       = require('../lib/store');
const { info, error } = require('../lib/formatter');

/**
 * tally add <item> [--count <n>]
 * Increments the tally for <item> by [count] (default 1).
 */
const addCmd = new Command('add')
  .description('Add to the tally for an item')
  .argument('<item>', 'Name of the item to tally')
  .option('-c, --count <n>', 'Amount to add', '1')
  .action((item, options) => {
    const amount = parseInt(options.count, 10);

    if (isNaN(amount) || amount < 1) {
      error('--count must be a positive integer');
      process.exit(1);
    }

    const data    = store.load();
    data[item]    = (data[item] ?? 0) + amount;
    store.save(data);

    info(`Added ${amount} to "${item}". New total: ${data[item]}`);
  });

module.exports = addCmd;
```

