### `src/lib/store.js`
```js
'use strict';

const fs   = require('fs');
const path = require('path');

const STORE_PATH = path.join(
  process.env.TALLY_STORE_DIR ?? process.env.HOME ?? '.',
  '.tally-store.json'
);

/**
 * Load the tally store from disk.
 * Returns an empty object if the file does not exist.
 * @returns {Record<string, number>}
 */
function load() {
  if (!fs.existsSync(STORE_PATH)) return {};

  try {
    const raw = fs.readFileSync(STORE_PATH, 'utf8');
    return JSON.parse(raw);
  } catch {
    throw new Error(`Failed to parse store at ${STORE_PATH}`);
  }
}

/**
 * Persist the tally store to disk.
 * @param {Record<string, number>} data
 */
function save(data) {
  fs.writeFileSync(STORE_PATH, JSON.stringify(data, null, 2), 'utf8');
}

/**
 * Delete the store file entirely.
 */
function clear() {
  if (fs.existsSync(STORE_PATH)) {
    fs.unlinkSync(STORE_PATH);
  }
}

module.exports = { load, save, clear, STORE_PATH };
```

