### `src/lib/formatter.js`
```js
'use strict';

const chalk = require('chalk');

const info  = (msg) => console.log(chalk.green('✔'), msg);
const warn  = (msg) => console.warn(chalk.yellow('⚠'), msg);
const error = (msg) => console.error(chalk.red('✖'), msg);

/**
 * Render a tally store as an aligned table.
 * @param {Record<string, number>} data
 * @returns {string}
 */
function table(data) {
  const entries = Object.entries(data);
  if (entries.length === 0) return chalk.dim('(no items tallied yet)');

  const maxLen = Math.max(...entries.map(([k]) => k.length));

  return entries
    .sort(([, a], [, b]) => b - a)                        // sort descending
    .map(([key, val]) => {
      const padded = key.padEnd(maxLen);
      return `  ${chalk.cyan(padded)}  ${chalk.bold(val)}`;
    })
    .join('\n');
}

module.exports = { info, warn, error, table };
```

