const store = require('../lib/store');

/**
 * Registers the `add` sub-command.
 * Usage: tally add <item> [amount]
 * @param {import('commander').Command} program
 */
function register(program) {
  program
    .command('add <item> [amount]')
    .description('Add to the tally for an item')
    .action(run);
}

/**
 * Core logic — exported separately so tests can call it directly.
 * @param {string} item
 * @param {string|undefined} amount
 * @returns {{ item: string, total: number }}
 */
function run(item, amount = '1') {
  const delta = parseInt(amount, 10);

  if (isNaN(delta) || delta <= 0) {
    throw new Error(`Amount must be a positive integer, got: "${amount}"`);
  }

  const total = store.increment(item, delta);
  console.log(`✔  ${item}: ${total}`);
  return { item, total };
}

module.exports = { register, run };
