### `src/lib/store.js`
```js
const fs   = require('fs');
const path = require('path');

const DATA_FILE = path.join(
  process.env.TALLY_DATA_DIR || require('os').homedir(),
  '.tally.json'
);

/** Read the current store from disk (or return empty object). */
function load() {
  try {
    return JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'));
  } catch {
    return {};
  }
}

/** Persist data to disk. */
function save(data) {
  fs.writeFileSync(DATA_FILE, JSON.stringify(data, null, 2));
}

/** Increment an item by delta and return the new total. */
function increment(item, delta = 1) {
  const data = load();
  data[item] = (data[item] ?? 0) + delta;
  save(data);
  return data[item];
}

/** Decrement an item (floor at 0) and return the new total. */
function decrement(item, delta = 1) {
  const data = load();
  data[item] = Math.max(0, (data[item] ?? 0) - delta);
  save(data);
  return data[item];
}

/** Remove an item entirely. */
function remove(item) {
  const data = load();
  const existed = item in data;
  delete data[item];
  save(data);
  return existed;
}

/** Return all entries. */
function getAll() {
  return load();
}

/** Wipe everything. */
function reset() {
  save({});
}

module.exports = { increment, decrement, remove, getAll, reset };
```

