```js
const store     = require('../lib/store');
const formatter = require('../lib/formatter');
const { TallyError } = require('../lib/errors');

/**
 * Increment the count of a named item.
 * @param {string} item   - The item name
 * @param {number} amount - How much to add (default 1)
 */
async function add(item, amount = 1) {
  if (!item || typeof item !== 'string') {
    throw new TallyError('Item name must be a non-empty string.');
  }
  if (!Number.isInteger(amount) || amount < 1) {
    throw new TallyError('Amount must be a positive integer.');
  }

  const data = await store.read();

  data[item] = (data[item] ?? 0) + amount;

  await store.write(data);

  console.log(formatter.success(`Added ${amount} to "${item}". New count: ${data[item]}`));
}

module.exports = add;
```

