### `src/lib/storage.js`
```js
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join }                                     from 'node:path';
import { homedir }                                  from 'node:os';

// Store data in ~/.tally.json
const DATA_PATH = join(homedir(), '.tally.json');

/**
 * Read the current tally data from disk.
 * @returns {Record<string, number>}
 */
export function readData() {
  if (!existsSync(DATA_PATH)) return {};

  try {
    return JSON.parse(readFileSync(DATA_PATH, 'utf8'));
  } catch {
    console.error('Error: could not parse tally data file');
    process.exit(1);
  }
}

/**
 * Write tally data to disk.
 * @param {Record<string, number>} data
 */
export function writeData(data) {
  writeFileSync(DATA_PATH, JSON.stringify(data, null, 2), 'utf8');
}
```

