### `src/lib/formatter.js`
```js
/**
 * Format a single item's count for display.
 * @param {string} item
 * @param {number} count
 * @returns {string}
 */
export function formatCount(item, count) {
  return `  ${item}: ${count}`;
}

/**
 * Format the full tally list for display.
 * @param {Record<string, number>} data
 * @returns {string}
 */
export function formatList(data) {
  const entries = Object.entries(data);

  if (entries.length === 0) {
    return 'No tallies yet. Use `tally add <item>` to start.';
  }

  return entries
    .sort(([, a], [, b]) => b - a)          // sort descending by count
    .map(([item, count]) => formatCount(item, count))
    .join('\n');
}
```

