    const lines  = result.split('\n').map(l => l.trim());

    assert.equal(lines[0], 'bananas: 7');
    assert.equal(lines[1], 'cherries: 4');
    assert.equal(lines[2], 'apples: 2');
  });

  it('formats multiple items', () => {
    const result = formatList({ x: 1, y: 2 });
    assert.match(result, /y: 2/);
    assert.match(result, /x: 1/);
  });
});
