### `src/commands/add.js`
```js
const store = require("../lib/store");

/**
 * Attach the `add` sub-command to the Commander program.
 * @param {import("commander").Command} program
 */
function register(program) {
  program
    .command("add <item>")
    .description("Increment the count for <item>")
    .option("-n, --amount <number>", "Amount to add", "1")
    .action((item, options) => {
      const amount = parseInt(options.amount, 10);

      if (isNaN(amount) || amount <= 0) {
        console.error("Error: --amount must be a positive integer.");
        process.exit(1);
      }

      const updated = execute(item, amount);
      console.log(`✔  ${item}: ${updated}`);
    });
}

/**
 * Pure business logic — increment an item's count.
 * Separated from Commander so it is easily unit-testable.
 *
 * @param {string} item
 * @param {number} amount
 * @returns {number} new count
 */
function execute(item, amount = 1) {
  const data = store.load();
  data[item] = (data[item] ?? 0) + amount;
  store.save(data);
  return data[item];
}

module.exports = { register, execute };
```

