### `tests/commands/add.test.js`
```js
const { execute } = require("../../src/commands/add");
const store       = require("../../src/lib/store");

// Isolate all tests from the real filesystem
jest.mock("../../src/lib/store");

describe("add command — execute()", () => {
  beforeEach(() => {
    jest.resetAllMocks();
  });

  test("adds 1 to a new item", () => {
    store.load.mockReturnValue({});

    const result = execute("apples");

    expect(result).toBe(1);
    expect(store.save).toHaveBeenCalledWith({ apples: 1 });
  });

  test("increments an existing item by 1", () => {
    store.load.mockReturnValue({ apples: 4 });

    const result = execute("apples");

    expect(result).toBe(5);
    expect(store.save).toHaveBeenCalledWith({ apples: 5 });
  });

  test("increments by a custom amount", () => {
    store.load.mockReturnValue({ apples: 2 });

    const result = execute("apples", 3);

    expect(result).toBe(5);
    expect(store.save).toHaveBeenCalledWith({ apples: 5 });
  });

  test("does not affect other items in the store", () => {
    store.load.mockReturnValue({ apples: 2, oranges: 7 });

    execute("apples", 1);

    expect(store.save).toHaveBeenCalledWith({ apples: 3, oranges: 7 });
  });
});
