### `tests/lib/store.test.js`
```js
const fs   = require("fs");
const path = require("path");
const os   = require("os");
const { load, save } = require("../../src/lib/store");

describe("store", () => {
  let tmpFile;

  beforeEach(() => {
    // Use a real temp file so we test actual I/O without touching production data
    tmpFile = path.join(os.tmpdir(), `tally-test-${Date.now()}.json`);
  });

  afterEach(() => {
    if (fs.existsSync(tmpFile)) fs.unlinkSync(tmpFile);
  });

  test("load() returns {} when file does not exist", () => {
    expect(load(tmpFile)).toEqual({});
  });

  test("load() parses an existing JSON file", () => {
    fs.writeFileSync(tmpFile, JSON.stringify({ apples: 3 }), "utf8");
    expect(load(tmpFile)).toEqual({ apples: 3 });
  });

  test("load() returns {} on malformed JSON", () => {
    fs.writeFileSync(tmpFile, "not-json", "utf8");
    expect(load(tmpFile)).toEqual({});
  });

  test("save() writes data as formatted JSON", () => {
    save({ apples: 5 }, tmpFile);
    const raw = fs.readFileSync(tmpFile, "utf8");
    expect(JSON.parse(raw)).toEqual({ apples: 5 });
  });

  test("save() then load() round-trips data correctly", () => {
    const data = { apples: 2, oranges: 9 };
    save(data, tmpFile);
    expect(load(tmpFile)).toEqual(data);
  });
});
```

