### Tests (`src/__tests__/`)

#### **`src/__tests__/capitalize.test.ts`**

Tests for the `capitalize` function.

```typescript
import { capitalize } from '../capitalize';

describe('capitalize', () => {
  it('should capitalize the first letter of a lowercase string', () => {
    expect(capitalize('hello')).toBe('Hello');
  });

  it('should return an empty string if given an empty string', () => {
    expect(capitalize('')).toBe('');
  });

  it('should not change a string that is already capitalized', () => {
    expect(capitalize('World')).toBe('World');
  });

  it('should handle single-character strings', () => {
    expect(capitalize('a')).toBe('A');
  });
});
```

#### **`src/__tests__/truncate.test.ts`**

Tests for the `truncate` function.

```typescript
import { truncate } from '../truncate';

describe('truncate', () => {
  it('should not truncate a string shorter than the max length', () => {
    const text = 'short text';
    expect(truncate(text, 20)).toBe('short text');
  });

  it('should not change a string equal to the max length', () => {
    const text = 'exact length';
    expect(truncate(text, 12)).toBe('exact length');
  });

  it('should truncate a string longer than the max length and add an ellipsis', () => {
    const text = 'This is a very long sentence.';
    expect(truncate(text, 10)).toBe('This is a ...');
  });

  it('should return an empty string if given an empty string', () => {
    expect(truncate('', 10)).toBe('');
  });
});
```

