const storage = require('../lib/storage');
const chalk = require('chalk');

exports.command = 'add <item> [count]';
exports.desc = 'Add an item to the tally';

exports.builder = {
  item: {
    describe: 'The item to add to the tally',
    type: 'string',
  },
  count: {
    describe: 'The number of times to add the item',
    type: 'number',
    default: 1,
  },
};

