```javascript
const fs = require('fs');
const path = require('path');

// A simple JSON file will act as our "database"
const TALLY_FILE = path.join(process.env.HOME || process.env.USERPROFILE, '.tally.json');

function readData() {
  try {
    if (fs.existsSync(TALLY_FILE)) {
      const rawData = fs.readFileSync(TALLY_FILE, 'utf-8');
      return JSON.parse(rawData);
    }
  } catch (error) {
    console.error('Error reading tally data:', error);
  }
  return {}; // Return empty object if file doesn't exist or is corrupt
}

function writeData(data) {
  try {
    fs.writeFileSync(TALLY_FILE, JSON.stringify(data, null, 2));
  } catch (error) {
    console.error('Error writing tally data:', error);
  }
}

module.exports = { readData, writeData };
```

