// commands/add.js
const storage = require('../lib/storage');

exports.command = 'add <item>';
exports.desc = 'Add an item to the tally';

exports.builder = (yargs) => {
  yargs.positional('item', {
    describe: 'The item to count',
    type: 'string',
  });
};

exports.handler = (argv) => {
  const data = storage.getData();
  const item = argv.item.toLowerCase();

  data[item] = (data[item] || 0) + 1;
  storage.saveData(data);

