#### `lib/storage.js`
This is for shared logic that multiple commands might use. In this case, it abstracts the logic for reading and writing the tally data to a JSON file, so your command files don't have to worry about `fs` operations.

```javascript
// lib/storage.js
const fs = require('fs');
const path = require('path');

// Use a file in the user's home directory to store data
const TALLY_FILE = path.join(process.env.HOME || process.env.USERPROFILE, '.tally.json');

function getData() {
  if (!fs.existsSync(TALLY_FILE)) {
    return {};
  }
  try {
    const content = fs.readFileSync(TALLY_FILE, 'utf-8');
    return JSON.parse(content);
  } catch (error) {
    console.error('Error reading tally file:', error);
    return {};
  }
}

function saveData(data) {
  try {
    fs.writeFileSync(TALLY_FILE, JSON.stringify(data, null, 2));
  } catch (error) {
    console.error('Error saving tally file:', error);
  }
}

module.exports = { getData, saveData };
```

