        ```javascript
        const fs = require('fs');
        const path = require('path');

        const TALLY_FILE = path.join(process.cwd(), 'tally.json');

        function getTally() {
          if (!fs.existsSync(TALLY_FILE)) {
            return {};
          }
          const content = fs.readFileSync(TALLY_FILE, 'utf-8');
          return JSON.parse(content);
        }

        function saveTally(data) {
          fs.writeFileSync(TALLY_FILE, JSON.stringify(data, null, 2));
        }

        function addTally(item) {
          const tally = getTally();
          tally[item] = (tally[item] || 0) + 1;
          saveTally(tally);
          return tally;
        }

        module.exports = { getTally, saveTally, addTally };
