```javascript
const storage = require('../utils/storage');

exports.command = 'add <item> [count]';
exports.desc = 'Add an item to the tally';

exports.builder = {
  item: {
    describe: 'The item to add to the tally',
    type: 'string',
  },
  count: {
    describe: 'How many to add',
    type: 'number',
    default: 1,
  },
};

exports.handler = async (argv) => {
