  const currentCount = tally[argv.item] || 0;
  tally[argv.item] = currentCount + argv.count;
  await storage.writeTally(tally);
  console.log(`Added ${argv.count} to '${argv.item}'. New total: ${tally[argv.item]}.`);
};
```

