```javascript
const fs = require('fs').promises;
const path = require('path');
const os = require('os');

const TALLY_FILE = path.join(os.homedir(), '.tally.json');

async function readTally() {
  try {
    const data = await fs.readFile(TALLY_FILE, 'utf8');
    return JSON.parse(data);
  } catch (error) {
    // If the file doesn't exist, return an empty object
    if (error.code === 'ENOENT') {
      return {};
    }
    throw error;
  }
}

async function writeTally(data) {
  await fs.writeFile(TALLY_FILE, JSON.stringify(data, null, 2));
}

module.exports = { readTally, writeTally };
```

