#### 5. `lib/utils/storage.js`

A utility module to abstract away the logic for reading and writing data. This makes your command files cleaner and your logic easier to test.

```javascript
const fs = require('fs');
const path = require('path');

// A simple JSON file will act as our "database"
const TALLY_FILE = path.join(process.cwd(), '.tally.json');

/**
 * Reads the tally data from the JSON file.
 * @returns {object} The tally data object.
 */
function getData() {
  try {
    if (fs.existsSync(TALLY_FILE)) {
      const rawData = fs.readFileSync(TALLY_FILE);
      return JSON.parse(rawData);
    }
  } catch (err) {
    console.error('Error reading tally file:', err);
  }
  return {}; // Return empty object if file doesn't exist or is invalid
}

/**
 * Writes the tally data to the JSON file.
 * @param {object} data The data to save.
 */
function saveData(data) {
  try {
    fs.writeFileSync(TALLY_FILE, JSON.stringify(data, null, 2));
  } catch (err) {
    console.error('Error writing to tally file:', err);
  }
}

module.exports = { getData, saveData };
```

