#### 4. `lib/storage.js` (Shared Logic)

This module centralizes the logic for interacting with the data source (e.g., a JSON file). This makes your commands cleaner and your storage logic easier to test and swap out.

```javascript
// lib/storage.js
const fs = require('fs');
const path = require('path');
const os = require('os');

// Store the data file in the user's home directory
const TALLY_FILE = path.join(os.homedir(), '.tally.json');

/**
 * Reads the tally data from the JSON file.
 * @returns {object} The parsed JSON data or an empty object.
 */
function read() {
  try {
    if (fs.existsSync(TALLY_FILE)) {
      const content = fs.readFileSync(TALLY_FILE, 'utf8');
      return JSON.parse(content);
    }
  } catch (err) {
    console.error('Error reading tally file:', err);
  }
  return {};
}

/**
 * Writes the tally data to the JSON file.
 * @param {object} data The data to write.
 */
function write(data) {
  try {
    fs.writeFileSync(TALLY_FILE, JSON.stringify(data, null, 2));
  } catch (err) {
    console.error('Error writing to tally file:', err);
  }
}

module.exports = { read, write, TALLY_FILE };
```

