#### 5. `test/commands/add.test.js` (Example Unit Test)

Here, we test the `add` command's handler in isolation. We use `jest.mock` to replace the actual `storage` module with a fake one, so our tests don't write real files and run instantly.

```javascript
// test/commands/add.test.js
const { handler } = require('../../commands/add');
const storage = require('../../lib/storage');

// Mock the storage module
jest.mock('../../lib/storage');

// Mock console.log and console.error to capture output
let consoleLogSpy;
let consoleErrorSpy;

beforeEach(() => {
  // Reset mocks before each test
  storage.read.mockClear();
  storage.write.mockClear();
  consoleLogSpy = jest.spyOn(console, 'log').mockImplementation(() => {});
  consoleErrorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
});

afterEach(() => {
  consoleLogSpy.mockRestore();
  consoleErrorSpy.mockRestore();
});

describe('add command handler', () => {
  it('should add a new item if it does not exist', () => {
    // Arrange: Mock storage to return an empty object
    storage.read.mockReturnValue({});
    const argv = { item: 'apple' };

    // Act: Run the handler
    handler(argv);

    // Assert: Check that write was called with the correct data
    expect(storage.write).toHaveBeenCalledWith({ apple: 0 });
    expect(consoleLogSpy).toHaveBeenCalledWith('Added "apple" to the tally list.');
  });

  it('should show an error if the item already exists', () => {
    // Arrange: Mock storage to return data with the item already present
    storage.read.mockReturnValue({ apple: 5 });
    const argv = { item: 'apple' };

    // Mock process.exit to prevent the test from stopping
    const exitSpy = jest.spyOn(process, 'exit').mockImplementation(() => {});

    // Act: Run the handler
    handler(argv);

    // Assert: Check that an error was logged and write was NOT called
    expect(storage.write).not.toHaveBeenCalled();
    expect(consoleErrorSpy).toHaveBeenCalledWith('Error: Item "apple" already exists.');
    expect(exitSpy).toHaveBeenCalledWith(1);

    exitSpy.mockRestore();
  });
});
```
This test setup ensures that you are only testing the logic inside `add.js`'s handler, not the file system or other dependencies.

