const fs = require('fs');
const path = require('path');

// A simple file-based storage for the total.
const TALLY_FILE = path.join(process.cwd(), '.tally.json');

function getTotal() {
  if (!fs.existsSync(TALLY_FILE)) {
    return 0;
  }
  try {
    const data = fs.readFileSync(TALLY_FILE, 'utf8');
    return JSON.parse(data).total || 0;
  } catch (error) {
    return 0;
  }
}

function setTotal(value) {
