const os = require('os');
const path = require('path');

// Use a file in the user's home directory to store data
const TALLY_FILE = path.join(os.homedir(), '.tally.json');

/**
 * Reads all scores from the storage file.
 * @returns {object} The scores object.
 */
function getScores() {
  if (!fs.existsSync(TALLY_FILE)) {
    return {};
  }
  const content = fs.readFileSync(TALLY_FILE, 'utf-8');
  return JSON.parse(content);
}

/**
 * Writes scores to the storage file.
 * @param {object} scores - The scores object to save.
 */
function saveScores(scores) {
  fs.writeFileSync(TALLY_FILE, JSON.stringify(scores, null, 2));
}

/**
 * Adds points to a specific item.
 * @param {string} item - The item to update.
 * @param {number} points - The points to add.
 * @returns {number} The new score for the item.
 */
function addScore(item, points) {
  const scores = getScores();
  scores[item] = (scores[item] || 0) + points;
  saveScores(scores);
  return scores[item];
}

// ... other functions like resetScores(), listScores(), etc.

module.exports = {
  getScores,
  saveScores,
  addScore,
};
```

