const storage = require('../../lib/storage');

// Mock the entire 'fs' module
jest.mock('fs');

describe('storage', () => {
  const MOCK_SCORES = { player1: 10, player2: 5 };

  beforeEach(() => {
    // Reset mocks before each test
    fs.existsSync.mockClear();
    fs.readFileSync.mockClear();
    fs.writeFileSync.mockClear();
  });

  describe('getScores', () => {
    it('should return an empty object if the file does not exist', () => {
      fs.existsSync.mockReturnValue(false);
      expect(storage.getScores()).toEqual({});
    });

    it('should return parsed scores if the file exists', () => {
      fs.existsSync.mockReturnValue(true);
      fs.readFileSync.mockReturnValue(JSON.stringify(MOCK_SCORES));
      expect(storage.getScores()).toEqual(MOCK_SCORES);
    });
  });

  describe('addScore', () => {
    it('should add points to a new item', () => {
      // Arrange: No file exists initially
      fs.existsSync.mockReturnValue(false);

      // Act
      storage.addScore('newUser', 5);

      // Assert: Check that writeFileSync was called with the correct new data
      const expectedData = JSON.stringify({ newUser: 5 }, null, 2);
