#### 2. `index.js` (The Main Entry Point)

This file is the dispatcher. It sets up `yargs` to find and execute commands from the `commands/` directory.

*   The `#!/usr/bin/env node` shebang line makes the file executable.
*   `yargs.commandDir('commands')` is the magic that automatically loads all command modules from the specified directory.

```javascript
#!/usr/bin/env node

const yargs = require('yargs/yargs');
const { hideBin } = require('yargs/helpers');

yargs(hideBin(process.argv))
  // Use the commands directory to find commands
  .commandDir('commands')
  // Enable --help and --version options
  .help()
  .alias('h', 'help')
  .version()
  .alias('v', 'version')
  // Demand a command is given
  .demandCommand(1, 'You need to provide a command.')
  // Useful for commands that fail
  .recommendCommands()
  .strict()
  .argv;
```

#### 3. `commands/` Directory

This directory holds the logic for each individual command, promoting modularity and clean code.

##### `commands/add.js`

Handles the `tally add <item>` command.

```javascript
const chalk = require('chalk');
const storage = require('../lib/storage');

exports.command = 'add <item> [n]';
exports.desc = 'Increment the count for an item';

exports.builder = {
  item: {
    describe: 'The item to tally',
    type: 'string',
  },
  n: {
    describe: 'Increment count by this number',
    type: 'number',
    default: 1,
  },
};

exports.handler = (argv) => {
  const data = storage.readData();
  const currentCount = data[argv.item] || 0;
  data[argv.item] = currentCount + argv.n;
  storage.writeData(data);

  console.log(
    `Added ${chalk.blue(argv.n)} to '${chalk.green(argv.item)}'. New total: ${chalk.yellow(data[argv.item])}`
  );
};
```

##### `commands/list.js`

Handles the `tally list` command.

```javascript
const chalk = require('chalk');
const storage = require('../lib/storage');

exports.command = 'list';
exports.desc = 'List all tallied items and their counts';

exports.handler = () => {
  const data = storage.readData();
  const items = Object.keys(data);

  if (items.length === 0) {
    console.log(chalk.yellow('No items have been tallied yet.'));
    return;
  }

  console.log(chalk.bold.underline('Current Tallies:'));
  items.forEach((item) => {
    console.log(`- ${chalk.green(item)}: ${chalk.yellow(data[item])}`);
  });
};
```

##### `commands/reset.js`

Handles the `tally reset <item>` command.

```javascript
const chalk = require('chalk');
const storage = require('../lib/storage');

exports.command = 'reset <item>';
exports.desc = 'Reset the count for a specific item to zero';

exports.handler = (argv) => {
  const data = storage.readData();
  if (data[argv.item] === undefined) {
    console.log(chalk.red(`Item '${argv.item}' not found.`));
    return;
  }

  data[argv.item] = 0;
  storage.writeData(data);
  console.log(chalk.green(`Item '${argv.item}' has been reset to 0.`));
};
```

#### 4. `lib/` Directory

For shared logic used across multiple commands.

##### `lib/storage.js`

A utility module to handle reading from and writing to a persistent JSON file. This abstracts away the file system logic.

```javascript
const fs = require('fs');
const path = require('path');
const os = require('os');

// Store data in a hidden file in the user's home directory
const dataPath = path.join(os.homedir(), '.tally.json');

const readData = () => {
  try {
    const rawData = fs.readFileSync(dataPath, 'utf8');
    return JSON.parse(rawData);
  } catch (error) {
    // If the file doesn't exist or is invalid JSON, return an empty object
    return {};
  }
};

const writeData = (data) => {
  fs.writeFileSync(dataPath, JSON.stringify(data, null, 2));
};

module.exports = { readData, writeData };
```

